(4689484, 676716, 12661, '<td valign="top">I like the three different presentations of faces to compose the triangle. As a suggestion (in no way a criticism) I think that if the photo and drawing were self-portraits, it would provide an interesting symmetry.</td>', 'I like the three different presentations of faces to compose the triangle. As a suggestion (in no way a criticism) I think that if the photo and drawing were self-portraits, it would provide an interesting symmetry.', '2008-05-08 02:39:56.000000', NULL, 1),
(4689499, 676282, 12661, '<td valign="top">Smart idea. This appeases both those looking for triangles and those looking for triangle composition. I really like the way the you used reflections to make the center objects look like a balanced stack. All in all, very well done.</td>', 'Smart idea. This appeases both those looking for triangles and those looking for triangle composition. I really like the way the you used reflections to make the center objects look like a balanced stack. All in all, very well done.', '2008-05-08 02:46:22.000000', NULL, 1),
(4689531, 675170, 82461, '<td valign="top">really very cute kid..... with gr8 smile.... :-)</td>', 'really very cute kid..... with gr8 smile.... :-)', '2008-05-08 03:04:27.000000', NULL, 1),
(4689553, 676063, 5364, '<td valign="top">Nice image, but you''ve lost a bit of contrast as the eye looks a bit washed out.</td>', 'Nice image, but you''ve lost a bit of contrast as the eye looks a bit washed out.', '2008-05-08 03:34:41.000000', NULL, 1),
