(4690609, 676095, 53416, '<td valign="top">Nice colour and tone, but am none too keen on the bluriness or the awkward little background spots.</td>', 'Nice colour and tone, but am none too keen on the bluriness or the awkward little background spots.', '2008-05-08 16:14:31.000000', NULL, 1),
