(4690620, 676543, 53416, '<td valign="top">Too much uninterresting space at the bottom of this in mu opinion.</td>', 'Too much uninterresting space at the bottom of this in mu opinion.', '2008-05-08 16:19:42.000000', NULL, 1),
(4690621, 676194, 53416, '<td valign="top">Great deatil and colours. The blurry background really works well too.  Well done!</td>', 'Great deatil and colours. The blurry background really works well too.  Well done!', '2008-05-08 16:20:22.000000', NULL, 1),
