(4691538, 676580, 55117, '<td valign="top">No it''s not.</td>', 'No it''s not.', '2008-05-08 23:52:37.000000', NULL, 1),
(4691539, 676285, 55117, '<td valign="top">Oh...hey...wires.</td>', 'Oh...hey...wires.', '2008-05-08 23:52:44.000000', NULL, 1),
(4691540, 676735, 55117, '<td valign="top">Why would you do this?</td>', 'Why would you do this?', '2008-05-08 23:52:57.000000', NULL, 1),
(4691543, 676637, 55117, '<td valign="top">Hey goose. You are poorly composed. Next time, find a new photographer who can more effectively capture your essence.</td>', 'Hey goose. You are poorly composed. Next time, find a new photographer who can more effectively capture your essence.', '2008-05-08 23:53:40.000000', NULL, 1),
(4691630, 676218, 62249, '<td valign="top">Lovely flowers. Highlights are blown out.</td>', 'Lovely flowers. Highlights are blown out.', '2008-05-09 01:16:22.000000', NULL, 1),
(4691634, 676648, 62249, '<td valign="top">Nice geometric composition that fits the challenge, but needs more contrast and improved tonal range.</td>', 'Nice geometric composition that fits the challenge, but needs more contrast and improved tonal range.', '2008-05-09 01:17:24.000000', NULL, 1),
(4691652, 675366, 62249, '<td valign="top">Good title.</td>', 'Good title.', '2008-05-09 01:22:37.000000', NULL, 1),
(4691655, 675632, 62249, '<td valign="top">Odd, but interesting. I''d like to see what you could do with this concept without the restrictions of Basic Editing. There''s potential in this idea.</td>', 'Odd, but interesting. I''d like to see what you could do with this concept without the restrictions of Basic Editing. There''s potential in this idea.', '2008-05-09 01:25:43.000000', NULL, 1),
(4691669, 676087, 62249, '<td valign="top">VERY nice. Ethereal. Well exposed. Good detail. Would have done well in Every Picture Tells a Story, too.</td>', 'VERY nice. Ethereal. Well exposed. Good detail. Would have done well in Every Picture Tells a Story, too.', '2008-05-09 01:33:24.000000', NULL, 1),
(4691671, 676646, 62249, '<td valign="top">Very nice. Like how you kept the highlight detail in the siding on the church, and you made very effective use of the triangular part of the wall in the foreground.</td>', 'Very nice. Like how you kept the highlight detail in the siding on the church, and you made very effective use of the triangular part of the wall in the foreground.', '2008-05-09 01:33:57.000000', NULL, 1),
(4691674, 675849, 62249, '<td valign="top">Love the creativity behind this one, and there are LOTS of triangles here. Good eye. The umbrella is a quirky yet very effective touch.</td>', 'Love the creativity behind this one, and there are LOTS of triangles here. Good eye. The umbrella is a quirky yet very effective touch.', '2008-05-09 01:36:09.000000', NULL, 1),
(4691679, 675529, 62249, '<td valign="top">Creative, funny, well composed, well exposed. Could benefit from a bit of sharpening, and touch out that white spot on sleeve when you''re not constrained by Basic Editing.</td>', 'Creative, funny, well composed, well exposed. Could benefit from a bit of sharpening, and touch out that white spot on sleeve when you''re not constrained by Basic Editing.', '2008-05-09 01:38:50.000000', NULL, 1),
(4691681, 676438, 62249, '<td valign="top">Good title, good shadow, good triangle, and just-right DOF.</td>', 'Good title, good shadow, good triangle, and just-right DOF.', '2008-05-09 01:39:48.000000', NULL, 1),
(4691682, 676439, 62249, '<td valign="top">This is quite cute and is very well shot, but I like the B/W version even better.</td>', 'This is quite cute and is very well shot, but I like the B/W version even better.', '2008-05-09 01:39:56.000000', NULL, 1),
(4691685, 676632, 62249, '<td valign="top">Interesting! Like the colors a lot, and the "bankers" are a unique element.</td>', 'Interesting! Like the colors a lot, and the "bankers" are a unique element.', '2008-05-09 01:40:21.000000', NULL, 1),
(4691686, 676005, 62249, '<td valign="top">Points for title! Good detail on bird on right.</td>', 'Points for title! Good detail on bird on right.', '2008-05-09 01:40:26.000000', NULL, 1),
(4691687, 676716, 62249, '<td valign="top">Nicely composed, and this shot works well in B/W. Good tonal range.</td>', 'Nicely composed, and this shot works well in B/W. Good tonal range.', '2008-05-09 01:40:41.000000', NULL, 1),
(4691688, 676683, 62249, '<td valign="top">Nicely exposed, and interesting choice of framing angle.</td>', 'Nicely exposed, and interesting choice of framing angle.', '2008-05-09 01:41:30.000000', NULL, 1),
(4691689, 676339, 62249, '<td valign="top">Good leaf detail and lovely background.</td>', 'Good leaf detail and lovely background.', '2008-05-09 01:41:41.000000', NULL, 1),
(4691695, 676743, 62249, '<td valign="top">This is a very pleasing photo. Seems like it should be illustrating some editorial piece in a magazine.</td>', 'This is a very pleasing photo. Seems like it should be illustrating some editorial piece in a magazine.', '2008-05-09 01:45:21.000000', NULL, 1),
(4691696, 676701, 62249, '<td valign="top">Well exposed, with good highlights while still retaining *some* shadow detail. It fits the challenge, but probably the triangle approach limited you compared to how you might otherwise shoot this subject.</td>', 'Well exposed, with good highlights while still retaining *some* shadow detail. It fits the challenge, but probably the triangle approach limited you compared to how you might otherwise shoot this subject.', '2008-05-09 01:45:25.000000', NULL, 1),
(4691697, 676428, 62249, '<td valign="top">I''m not usually a purple/pink lover, but something about this photo compels me to look at it again and again. I like the contrasty look. It just fits the tulips well.</td>', 'I''m not usually a purple/pink lover, but something about this photo compels me to look at it again and again. I like the contrasty look. It just fits the tulips well.', '2008-05-09 01:47:46.000000', NULL, 1),
(4691699, 676367, 90624, '<td valign="top">Triangles or Rectangles?</td>', 'Triangles or Rectangles?', '2008-05-09 01:48:37.000000', NULL, 1),
(4691700, 676796, 90624, '<td valign="top">Blurred.. made my eyes go goofy...</td>', 'Blurred.. made my eyes go goofy...', '2008-05-09 01:50:04.000000', NULL, 1),
(4691726, 676613, 78132, '<td valign="top">Simply beautiful, but technically not a triangle but rather an angle unless the glasses themselves are triangles. Colors and composition are wonderful so, still a 10 to me :)</td>', 'Simply beautiful, but technically not a triangle but rather an angle unless the glasses themselves are triangles. Colors and composition are wonderful so, still a 10 to me :)', '2008-05-09 02:15:43.000000', NULL, 1),
(4691790, 676600, 5364, '<td valign="top">Good picture and you might have found that using a polarising filter would have darkened the sky and made it slightly more dramatic.</td>', 'Good picture and you might have found that using a polarising filter would have darkened the sky and made it slightly more dramatic.', '2008-05-09 03:51:33.000000', NULL, 1),
(4691797, 676735, 5364, '<td valign="top">Interesting texture, but it''s rather lacking in contrast</td>', 'Interesting texture, but it''s rather lacking in contrast', '2008-05-09 03:55:27.000000', NULL, 1),
(4691861, 676667, 49578, '<td valign="top">I think what is lacking in this image is three key/amchor points which will qualify it for a triangle composition. <br/>Apart from that, the flower itself does not look very fresh and there is nothing special about the lighting too</td>', 'I think what is lacking in this image is three key/amchor points which will qualify it for a triangle composition. Apart from that, the flower itself does not look very fresh and there is nothing special about the lighting too', '2008-05-09 05:45:42.000000', NULL, 1),
(4691901, 676643, 49578, '<td valign="top">I like the way the planes are arranged along the diagonly, but this is truly a bit far-fetched candidate for triangle composition</td>', 'I like the way the planes are arranged along the diagonly, but this is truly a bit far-fetched candidate for triangle composition', '2008-05-09 06:18:54.000000', NULL, 1),
(4691906, 676733, 49578, '<td valign="top">The colours are very nice, the yellow, the green and black to punctuate. I hate to deduct points for not exactly meeting the challenge description, but composition wise, i cannot find the elements which imply a triangle in the frame. But i like the picture</td>', 'The colours are very nice, the yellow, the green and black to punctuate. I hate to deduct points for not exactly meeting the challenge description, but composition wise, i cannot find the elements which imply a triangle in the frame. But i like the picture', '2008-05-09 06:25:25.000000', NULL, 1),
(4692122, 675529, 92847, '<td valign="top">You had a good ideia. Very creative photo!</td>', 'You had a good ideia. Very creative photo!', '2008-05-09 10:07:24.000000', NULL, 1),
(4692128, 676033, 92847, '<td valign="top">Congratulations! Very nice photo!! is not easy take this exact moment! I realy love your composition!</td>', 'Congratulations! Very nice photo!! is not easy take this exact moment! I realy love your composition!', '2008-05-09 10:10:55.000000', NULL, 1),
(4692581, 676218, 34255, '<td valign="top">Nice subject, but it''s overexposed and if there is an implied triangle, it''s very subtle.</td>', 'Nice subject, but it''s overexposed and if there is an implied triangle, it''s very subtle.', '2008-05-09 12:52:26.000000', NULL, 1),
(4692582, 675902, 34255, '<td valign="top">Fits the challenge well, and a good quality photo, but I don''t like the desaturation.</td>', 'Fits the challenge well, and a good quality photo, but I don''t like the desaturation.', '2008-05-09 12:55:31.000000', NULL, 1),
(4692587, 676841, 34255, '<td valign="top">This does fit the challenge as you have some good implied triangles, but the lighting/exposure is pretty poor.</td>', 'This does fit the challenge as you have some good implied triangles, but the lighting/exposure is pretty poor.', '2008-05-09 12:57:05.000000', NULL, 1),
(4692594, 676632, 34134, '<td valign="top">I don''t know what I''m looking at, but I LOVE IT!!</td>', 'I don''t know what I''m looking at, but I LOVE IT!!', '2008-05-09 13:02:13.000000', NULL, 1),
(4692600, 676302, 34255, '<td valign="top">I really like the composition of this, though I don''t really like the border.</td>', 'I really like the composition of this, though I don''t really like the border.', '2008-05-09 13:05:02.000000', NULL, 1),
(4692617, 676146, 53416, '<td valign="top">Interesting lighting.  And I wonder how you got the smoke to look like that?</td>', 'Interesting lighting.  And I wonder how you got the smoke to look like that?', '2008-05-09 13:21:33.000000', NULL, 1),
(4692619, 676410, 53416, '<td valign="top">Nice and sharp, with good detail and a nice blurry background.  Well done.</td>', 'Nice and sharp, with good detail and a nice blurry background.  Well done.', '2008-05-09 13:22:14.000000', NULL, 1),
(4692622, 676155, 53416, '<td valign="top">I think this works a bit better if you crop off a bit of the empty sky on the left.  Good effort though.</td>', 'I think this works a bit better if you crop off a bit of the empty sky on the left.  Good effort though.', '2008-05-09 13:24:38.000000', NULL, 1),
(4692624, 675170, 53416, '<td valign="top">Doesn''t feel very triangular in composition!  Sharp, and with a great shallow depth of field.  Very nicely done!</td>', 'Doesn''t feel very triangular in composition!  Sharp, and with a great shallow depth of field.  Very nicely done!', '2008-05-09 13:25:44.000000', NULL, 1),
(4692625, 676789, 53416, '<td valign="top">Nice use of pattern and repetition.  Thought provoking too.</td>', 'Nice use of pattern and repetition.  Thought provoking too.', '2008-05-09 13:26:41.000000', NULL, 1),
(4692630, 676707, 53416, '<td valign="top">Nice subtle composition formed with the arm.</td>', 'Nice subtle composition formed with the arm.', '2008-05-09 13:28:12.000000', NULL, 1),
(4692631, 676348, 53416, '<td valign="top">Nice contrast, textures and detail.</td>', 'Nice contrast, textures and detail.', '2008-05-09 13:28:15.000000', NULL, 1),
(4692635, 676611, 53416, '<td valign="top">Doesn''t feel very triangular in composition to me!  I love the colour of the sky and the sense of scale though.</td>', 'Doesn''t feel very triangular in composition to me!  I love the colour of the sky and the sense of scale though.', '2008-05-09 13:29:14.000000', NULL, 1),
(4692638, 675390, 53416, '<td valign="top">A cute picture, but could be sharper.</td>', 'A cute picture, but could be sharper.', '2008-05-09 13:29:42.000000', NULL, 1),
(4692641, 676758, 53416, '<td valign="top">Great texture, detail and contrast.  Nice depth of field too.  This is very nice!</td>', 'Great texture, detail and contrast.  Nice depth of field too.  This is very nice!', '2008-05-09 13:30:26.000000', NULL, 1),
(4692642, 676827, 53416, '<td valign="top">Not very triangular in composition!  But I really like the rich colours.</td>', 'Not very triangular in composition!  But I really like the rich colours.', '2008-05-09 13:31:08.000000', NULL, 1),
(4692644, 676360, 53416, '<td valign="top">Nice textures and detail.</td>', 'Nice textures and detail.', '2008-05-09 13:32:09.000000', NULL, 1),
(4692646, 676214, 53416, '<td valign="top">Interseting composition and quite minimalist.  I wonder what they''re doing or depicting.....</td>', 'Interseting composition and quite minimalist.  I wonder what they''re doing or depicting.....', '2008-05-09 13:33:14.000000', NULL, 1),
(4692649, 676748, 53416, '<td valign="top">A good low key photograph, with a subtle triangular composition.  Makes me wonder what''s going through his head....?</td>', 'A good low key photograph, with a subtle triangular composition.  Makes me wonder what''s going through his head....?', '2008-05-09 13:34:40.000000', NULL, 1),
(4692650, 675427, 53416, '<td valign="top">Nice abstract photograph with good colours.</td>', 'Nice abstract photograph with good colours.', '2008-05-09 13:35:25.000000', NULL, 1),
(4692653, 675968, 53416, '<td valign="top">Nice sharp close up photograph.  I love the red and the textures in the reflector.</td>', 'Nice sharp close up photograph.  I love the red and the textures in the reflector.', '2008-05-09 13:36:24.000000', NULL, 1),
(4692654, 676282, 53416, '<td valign="top">Great contrast, textures and use of symmetry.  The reflections work really well.  Well done!</td>', 'Great contrast, textures and use of symmetry.  The reflections work really well.  Well done!', '2008-05-09 13:37:32.000000', NULL, 1),
(4692655, 676847, 53416, '<td valign="top">Good perspective and use of repetitious details.</td>', 'Good perspective and use of repetitious details.', '2008-05-09 13:38:28.000000', NULL, 1),
(4692660, 676391, 53416, '<td valign="top">Nice composition with good contrast.  I think a lone figure on the far platform would work really well here.</td>', 'Nice composition with good contrast.  I think a lone figure on the far platform would work really well here.', '2008-05-09 13:39:45.000000', NULL, 1),
(4692663, 676444, 53416, '<td valign="top">I love the blurry pattern formed by the light on the water in the background.  Wish the swans were a bit sharper though.</td>', 'I love the blurry pattern formed by the light on the water in the background.  Wish the swans were a bit sharper though.', '2008-05-09 13:41:54.000000', NULL, 1),
(4692664, 676701, 53416, '<td valign="top">I love the colours in the stained glass window.  Nice!</td>', 'I love the colours in the stained glass window.  Nice!', '2008-05-09 13:42:33.000000', NULL, 1),
(4692665, 675920, 53416, '<td valign="top">Nice action capture, but the triangular element is soooooo very subtle!</td>', 'Nice action capture, but the triangular element is soooooo very subtle!', '2008-05-09 13:43:12.000000', NULL, 1),
(4692667, 676206, 53416, '<td valign="top">Great colours and well composed.  The bold border works really well too.  Nice!</td>', 'Great colours and well composed.  The bold border works really well too.  Nice!', '2008-05-09 13:44:01.000000', NULL, 1),
(4692671, 676700, 53416, '<td valign="top">Nice capture of a tricky subject!  The photograph is too dark though - a lot of detail is lost in the bird.  I think a bit of tweaking with Levels and Curves could make this a even better.</td>', 'Nice capture of a tricky subject!  The photograph is too dark though - a lot of detail is lost in the bird.  I think a bit of tweaking with Levels and Curves could make this a even better.', '2008-05-09 13:49:26.000000', NULL, 1),
(4692672, 676618, 53416, '<td valign="top">Quite sharp and with nice detail in the bricks.</td>', 'Quite sharp and with nice detail in the bricks.', '2008-05-09 13:50:25.000000', NULL, 1),
(4692674, 676005, 53416, '<td valign="top">How did you manage to get this photo?  Nice depth of field, but the lighting feels a bit harsh.</td>', 'How did you manage to get this photo?  Nice depth of field, but the lighting feels a bit harsh.', '2008-05-09 13:51:24.000000', NULL, 1),
(4692678, 676617, 53416, '<td valign="top">Great lighting with very pleasing reflections.  I love the curves.</td>', 'Great lighting with very pleasing reflections.  I love the curves.', '2008-05-09 13:53:16.000000', NULL, 1),
(4692680, 676240, 53416, '<td valign="top">Nice depth of field and use of complimentary colours.  The lighting is very good too.</td>', 'Nice depth of field and use of complimentary colours.  The lighting is very good too.', '2008-05-09 13:54:13.000000', NULL, 1),
(4692681, 676087, 53416, '<td valign="top">Very nice!  Makes me wonder where they are and what''s going on - has a very dreamlike feel to it.  Nice composition and contrast too.</td>', 'Very nice!  Makes me wonder where they are and what''s going on - has a very dreamlike feel to it.  Nice composition and contrast too.', '2008-05-09 13:55:35.000000', NULL, 1),
(4692682, 675637, 53416, '<td valign="top">Nice details and texture, with a nice depth of field too.</td>', 'Nice details and texture, with a nice depth of field too.', '2008-05-09 13:56:22.000000', NULL, 1),
(4692684, 676457, 53416, '<td valign="top">Interesting composition and the tilt works quite well too.  The foreground detail is too gloomy though - a bit of tweaing of Levels and Curves could make this much better.</td>', 'Interesting composition and the tilt works quite well too.  The foreground detail is too gloomy though - a bit of tweaing of Levels and Curves could make this much better.', '2008-05-09 14:02:08.000000', NULL, 1),
(4692687, 675849, 53416, '<td valign="top">Interesting composition.  Makes me wonder why the person in the foreground is hiding behind the umberella....?!</td>', 'Interesting composition.  Makes me wonder why the person in the foreground is hiding behind the umberella....?!', '2008-05-09 14:04:19.000000', NULL, 1),
(4692689, 675552, 53416, '<td valign="top">Quite and odd subject pairing!  Nice depth of field and textures.</td>', 'Quite and odd subject pairing!  Nice depth of field and textures.', '2008-05-09 14:05:19.000000', NULL, 1),
(4692690, 676218, 53416, '<td valign="top">Too centrally composed, and the highlights in the yellow flower are over blown.</td>', 'Too centrally composed, and the highlights in the yellow flower are over blown.', '2008-05-09 14:05:55.000000', NULL, 1),
(4692691, 676438, 53416, '<td valign="top">Great depth of field, sharp and interesting to look at.  I like this a lot.  Well done!</td>', 'Great depth of field, sharp and interesting to look at.  I like this a lot.  Well done!', '2008-05-09 14:06:43.000000', NULL, 1),
(4692692, 676065, 53416, '<td valign="top">Interesting composition and tilt, but doesn''t really hold my interest long.</td>', 'Interesting composition and tilt, but doesn''t really hold my interest long.', '2008-05-09 14:07:24.000000', NULL, 1),
(4692694, 676598, 53416, '<td valign="top">Nice blurry background, but I wish more of the cone things were in focus.</td>', 'Nice blurry background, but I wish more of the cone things were in focus.', '2008-05-09 14:08:01.000000', NULL, 1),
(4692695, 675918, 53416, '<td valign="top">Great contrasting background and very pleasing colours.</td>', 'Great contrasting background and very pleasing colours.', '2008-05-09 14:08:30.000000', NULL, 1),
(4692697, 676439, 53416, '<td valign="top">Nice colours.</td>', 'Nice colours.', '2008-05-09 14:09:30.000000', NULL, 1),
(4692698, 676610, 53416, '<td valign="top">Nice depth of field.</td>', 'Nice depth of field.', '2008-05-09 14:09:51.000000', NULL, 1),
(4692700, 676644, 53416, '<td valign="top">What a unique staircase.  I like the reflections in it too.</td>', 'What a unique staircase.  I like the reflections in it too.', '2008-05-09 14:11:16.000000', NULL, 1),
(4692703, 676613, 53416, '<td valign="top">Nice and sharp and well done.  The background works quite nicely too.  Well done.</td>', 'Nice and sharp and well done.  The background works quite nicely too.  Well done.', '2008-05-09 14:12:27.000000', NULL, 1),
(4692704, 675731, 53416, '<td valign="top">The brown angainst the red backgound works well, but the lighting is a bit harsh.</td>', 'The brown angainst the red backgound works well, but the lighting is a bit harsh.', '2008-05-09 14:13:22.000000', NULL, 1),
(4692705, 676632, 53416, '<td valign="top">Looks like a Banksy to me!  Nice foreground texture and colours.</td>', 'Looks like a Banksy to me!  Nice foreground texture and colours.', '2008-05-09 14:14:16.000000', NULL, 1),
(4692706, 675042, 53416, '<td valign="top">Doesn''t really hold my interest - sorry.</td>', 'Doesn''t really hold my interest - sorry.', '2008-05-09 14:14:40.000000', NULL, 1),
