(4693917, 676743, 5364, '<td valign="top">This is a nice enough image but, after some study, I think it''s the fact that the horsemen are so close to the edge and facing out of the frame that I''m not keen on.</td>', 'This is a nice enough image but, after some study, I think it''s the fact that the horsemen are so close to the edge and facing out of the frame that I''m not keen on.', '2008-05-10 12:37:48.000000', NULL, 1),
(4693921, 676643, 5364, '<td valign="top">I like the subject and the composition is good, but I think you''ve been let down by the weather. The grey sky has robbed you of a little extra drama.</td>', 'I like the subject and the composition is good, but I think you''ve been let down by the weather. The grey sky has robbed you of a little extra drama.', '2008-05-10 12:40:52.000000', NULL, 1),
