INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4700502, 676748, 68573, '<td valign="top">Great lighting and very nice portrayal of the theme</td>', 'Great lighting and very nice portrayal of the theme', '2008-05-14 00:38:33.000000', NULL, 1),
(4700505, 676632, 88204, '<td valign="top">It doesn''t have enough context for me to wrap my head around it.</td>', 'It doesn''t have enough context for me to wrap my head around it.', '2008-05-14 00:40:17.000000', NULL, 1),
(4700511, 676512, 88204, '<td valign="top">Good triangle composition. The girl on the right''s expression is to die for! The mom''s eyes are closed which runis the shot for me. The girl on the left is adorable but seems not quite sharp, or maybe it''s that both of her eyes are in shadow. Lighting for the girl on the right is outstanding... perfect hint of light in her eye to make it sparkle.</td>', 'Good triangle composition. The girl on the right''s expression is to die for! The mom''s eyes are closed which runis the shot for me. The girl on the left is adorable but seems not quite sharp, or maybe it''s that both of her eyes are in shadow. Lighting for the girl on the right is outstanding... perfect hint of light in her eye to make it sparkle.', '2008-05-14 00:42:22.000000', NULL, 1),
(4700516, 676644, 88204, '<td valign="top">Very cool staircase. It doesn''t make a great photo but it looks interesting.</td>', 'Very cool staircase. It doesn''t make a great photo but it looks interesting.', '2008-05-14 00:43:05.000000', NULL, 1),
(4700519, 676446, 88204, '<td valign="top">Good composition but it leaves me wanting more of a subject.</td>', 'Good composition but it leaves me wanting more of a subject.', '2008-05-14 00:43:30.000000', NULL, 1),
(4700522, 676642, 88204, '<td valign="top">Black and white works great for this. Certainly a strong triange.</td>', 'Black and white works great for this. Certainly a strong triange.', '2008-05-14 00:43:55.000000', NULL, 1),
(4700529, 676418, 88204, '<td valign="top">Beautiful lighting, exposure and detail. I''m not sure I get the triangle composition but the image is good enough that I''ll assume it''s there and I''m just not getting it (i.e. I won''t mark you down for it).</td>', 'Beautiful lighting, exposure and detail. I''m not sure I get the triangle composition but the image is good enough that I''ll assume it''s there and I''m just not getting it (i.e. I won''t mark you down for it).', '2008-05-14 00:44:58.000000', NULL, 1),
(4700531, 676837, 88204, '<td valign="top">Very gentle and intimate shot. I''m assuming the triangle is inverted with the eyebrows to mouth-- not super strong triangle composition but I still really like the image.</td>', 'Very gentle and intimate shot. I''m assuming the triangle is inverted with the eyebrows to mouth-- not super strong triangle composition but I still really like the image.', '2008-05-14 00:45:55.000000', NULL, 1),
(4700533, 676809, 88204, '<td valign="top">Great contrast and detail!</td>', 'Great contrast and detail!', '2008-05-14 00:46:13.000000', NULL, 1),
(4700535, 676683, 88204, '<td valign="top">Beautiful lighting. I''d love to hear more details on how you lit this.</td>', 'Beautiful lighting. I''d love to hear more details on how you lit this.', '2008-05-14 00:47:13.000000', NULL, 1),
(4700536, 676543, 88204, '<td valign="top">Very simple and focused. I don''t like the stick and clip in the shot.</td>', 'Very simple and focused. I don''t like the stick and clip in the shot.', '2008-05-14 00:47:45.000000', NULL, 1),
(4700539, 676732, 88204, '<td valign="top">Pacman! Interesting composition.</td>', 'Pacman! Interesting composition.', '2008-05-14 00:48:41.000000', NULL, 1),
(4700557, 676613, 32108, '<td valign="top">You inspire me girl!!!</td>', 'You inspire me girl!!!', '2008-05-14 01:02:46.000000', NULL, 0),
(4700567, 676613, 64929, '<td valign="top">OMG Irene!  You are AMAZING!  You may end up setting a record for consecutive ribbons!  I''m in awe....CONGRATS, dear friend!</td>', 'OMG Irene!  You are AMAZING!  You may end up setting a record for consecutive ribbons!  I''m in awe....CONGRATS, dear friend!', '2008-05-14 01:04:03.000000', NULL, 0),
(4700568, 676613, 48228, '<td valign="top">Way to go Irene and you are on a roll this year with your amazing images and talent..... This was my pick for a ribbon winner, and a <b>BLUE</b> at that and it is just..... I gave this a 10..........</td>', 'Way to go Irene and you are on a roll this year with your amazing images and talent..... This was my pick for a ribbon winner, and a BLUE at that and it is just..... I gave this a 10..........', '2008-05-14 01:04:03.000000', NULL, 0),
(4700573, 675529, 48228, '<td valign="top">Pretty clever with this awesome composition and deserved the <b>RED ribbon.....</b></td>', 'Pretty clever with this awesome composition and deserved the RED ribbon.....', '2008-05-14 01:04:50.000000', NULL, 0),
(4700580, 675521, 51793, '<td valign="top">Look at you getting a top 10, Congrats, though I don''t think that you deserved all those 1''s.</td>', 'Look at you getting a top 10, Congrats, though I don''t think that you deserved all those 1''s.', '2008-05-14 01:06:03.000000', NULL, 0),
(4700582, 676339, 48228, '<td valign="top">Well done on achieving a <b>YELLOW</b> ribbon, for this strong triangle image.....</td>', 'Well done on achieving a YELLOW ribbon, for this strong triangle image.....', '2008-05-14 01:06:26.000000', NULL, 0),
(4700585, 676154, 48228, '<td valign="top">I had this one picked as a ribbon contender, as I really love this idea.....</td>', 'I had this one picked as a ribbon contender, as I really love this idea.....', '2008-05-14 01:07:11.000000', NULL, 0),
(4700589, 676740, 80904, '<td valign="top">ha! you got me beat. Good job Greg!</td>', 'ha! you got me beat. Good job Greg!', '2008-05-14 01:08:36.000000', NULL, 0),
(4700592, 676613, 19936, '<td valign="top">Ok, you have the DPC voters wrapped around your finger now.  Geez, last six challenges and you have 2 blues, 2 reds and a yellow!  Your shots are right on the mark lately, not that they have not always been pretty darn good.  Congratulation!</td>', 'Ok, you have the DPC voters wrapped around your finger now.  Geez, last six challenges and you have 2 blues, 2 reds and a yellow!  Your shots are right on the mark lately, not that they have not always been pretty darn good.  Congratulation!', '2008-05-14 01:10:07.000000', NULL, 0),
(4700595, 676613, 67697, '<td valign="top">So clever.  I love the background too.  Congrats on the blue!</td>', 'So clever.  I love the background too.  Congrats on the blue!', '2008-05-14 01:10:26.000000', NULL, 0),
(4700596, 675521, 19936, '<td valign="top">I thought this was a ribbon for sure.  Great shot.  You was robbed.</td>', 'I thought this was a ribbon for sure.  Great shot.  You was robbed.', '2008-05-14 01:11:11.000000', NULL, 0),
(4700618, 675529, 80904, '<td valign="top">I like to see shots like this one win. Great originality. Grats on the ribbon</td>', 'I like to see shots like this one win. Great originality. Grats on the ribbon', '2008-05-14 01:17:25.000000', NULL, 0),
(4700626, 676613, 49643, '<td valign="top">Big Congratulations on Blue!!</td>', 'Big Congratulations on Blue!!', '2008-05-14 01:18:27.000000', NULL, 0),
