(4700645, 676428, 75386, '<td valign="top">Nice PP on this! grainy and colorful.<br/> <br/>If you have a sec, lemme know how you did it</td>', 'Nice PP on this! grainy and colorful. If you have a sec, lemme know how you did it', '2008-05-14 01:22:13.000000', NULL, 0),
(4700658, 675849, 67697, '<td valign="top">Awesome Panos!  There are soooooo many triangles in this!  (I like the ones in the umbrella too)  Oh I did not even notice the third person!  Excellent catch and congrats on 11th place!</td>', 'Awesome Panos!  There are soooooo many triangles in this!  (I like the ones in the umbrella too)  Oh I did not even notice the third person!  Excellent catch and congrats on 11th place!', '2008-05-14 01:25:30.000000', NULL, 0),
