(4700677, 676613, 32872, '<td valign="top">Congratulations on the Blue. This is amazing!</td>', 'Congratulations on the Blue. This is amazing!', '2008-05-14 01:29:05.000000', NULL, 0),
(4700682, 676439, 66384, '<td valign="top">How delightful. Beautiful light and composition.</td>', 'How delightful. Beautiful light and composition.', '2008-05-14 01:30:23.000000', NULL, 0),
