INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4710182, 676789, 20577, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by shundaroni:</b></div><hr/><i> Tablets. Endless tablets. I understand how it could be confusing. Both "triangles" and "tablets" begin with the letter "T". </i></td></tr></table> <br/> <br/>Great comment... a-hole!</td>', 'Originally posted by shundaroni: Tablets. Endless tablets. I understand how it could be confusing. Both "triangles" and "tablets" begin with the letter "T".   Great comment... a-hole!', '2008-05-18 22:57:24.000000', NULL, 0),
(4710349, 676666, 79847, '<td valign="top">Hi, thanks for your great comment.  This was my favourite photo in this catagory, I''m surprised it didn''t get a ribbon.  Love your portfolio, i hope I progress to produce pictures like yours.</td>', 'Hi, thanks for your great comment.  This was my favourite photo in this catagory, I''m surprised it didn''t get a ribbon.  Love your portfolio, i hope I progress to produce pictures like yours.', '2008-05-19 00:33:55.000000', NULL, 0),
(4710628, 676571, 66515, '<td valign="top">Nice shot here. Your friend''s eye are a little soft however, you were shooting f/2 on a squirrel who are not known for being especially patient with photographers. A smaller aperture may have granted you enough depth of field to get his (her?) whole face in focus while still having the blurred background.<br/> <br/>As for the challenge? I see two triangles here formed by eyes and nose then paws and nose/peanut. <br/> <br/>Overall, a great shot that landed you in the top third.</td>', 'Nice shot here. Your friend''s eye are a little soft however, you were shooting f/2 on a squirrel who are not known for being especially patient with photographers. A smaller aperture may have granted you enough depth of field to get his (her?) whole face in focus while still having the blurred background. As for the challenge? I see two triangles here formed by eyes and nose then paws and nose/peanut.  Overall, a great shot that landed you in the top third.', '2008-05-19 02:39:14.000000', NULL, 0),
(4711213, 676266, 27421, '<td valign="top">During voting I gave it a 7... I didn''t notice the reflections of the overhead lights until now, I usually don''t nit-pick and go over an image brfore I score it...I usually score on initial impact, which still remains a 7. ( I wonder if objects could be repositioned to eliminate light reflections, unless of course, they were intended...)<br/><br/><i>Message edited by author 2008-05-19 10:50:11.</i></td>', 'During voting I gave it a 7... I didn''t notice the reflections of the overhead lights until now, I usually don''t nit-pick and go over an image brfore I score it...I usually score on initial impact, which still remains a 7. ( I wonder if objects could be repositioned to eliminate light reflections, unless of course, they were intended...)', '2008-05-19 11:48:32.000000', '2008-05-19 11:50:11.000000', 0),
